// ======================================================
// STORE GATEWAYS
// ======================================================

const component = "gateways";

try {

    // --------------------------------------------------
    // PARSEAR JSON
    // --------------------------------------------------

    const gateways = JSON.parse(msg.payload);


    // --------------------------------------------------
    // VALIDACIÓN BÁSICA
    // --------------------------------------------------

    if (
        !gateways ||
        typeof gateways !== "object" ||
        Array.isArray(gateways)
    ) {
        throw new Error(
            "gateways.json no contiene un objeto JSON válido."
        );
    }


    const gatewayIds = Object.keys(gateways);


    if (gatewayIds.length === 0) {
        throw new Error(
            "gateways.json no contiene gateways."
        );
    }


    // --------------------------------------------------
    // GUARDAR CONFIGURACIÓN
    // --------------------------------------------------

    global.set("gateways", gateways);


    // --------------------------------------------------
    // ESTADO
    // --------------------------------------------------

    node.status({
        fill: "green",
        shape: "dot",
        text: gatewayIds.length + " gateways"
    });


    // --------------------------------------------------
    // EVENTO PARA STARTUP COORDINATOR
    // --------------------------------------------------

    msg.startupEvent = {

        component: component,

        ok: true,

        count: gatewayIds.length,

        error: null,

        timestamp: new Date().toISOString()

    };


    msg.payload = gateways;

    return msg;


} catch (err) {

    // Una configuración inválida NO debe conservarse
    // como válida en memoria.

    global.set("gateways", null);


    node.status({
        fill: "red",
        shape: "ring",
        text: "ERROR"
    });


    msg.startupEvent = {

        component: component,

        ok: false,

        count: 0,

        error: err.message,

        timestamp: new Date().toISOString()

    };


    msg.payload = null;

    return msg;
}

// ======================================================
// STORE DEVICES
// ======================================================

const component = "devices";

try {

    // --------------------------------------------------
    // PARSEAR JSON
    // --------------------------------------------------

    const devices = JSON.parse(msg.payload);


    // --------------------------------------------------
    // VALIDACIÓN BÁSICA
    // --------------------------------------------------

    if (
        !devices ||
        typeof devices !== "object" ||
        Array.isArray(devices)
    ) {
        throw new Error(
            "devices.json no contiene un objeto JSON válido."
        );
    }


    const deviceIds = Object.keys(devices);


    if (deviceIds.length === 0) {
        throw new Error(
            "devices.json no contiene dispositivos."
        );
    }


    // --------------------------------------------------
    // GUARDAR CONFIGURACIÓN
    // --------------------------------------------------

    global.set("devices", devices);


    // --------------------------------------------------
    // ESTADO VISUAL
    // --------------------------------------------------

    node.status({
        fill: "green",
        shape: "dot",
        text: deviceIds.length + " devices"
    });


    // --------------------------------------------------
    // EVENTO PARA STARTUP COORDINATOR
    // --------------------------------------------------

    msg.startupEvent = {

        component: component,

        ok: true,

        count: deviceIds.length,

        error: null,

        timestamp: new Date().toISOString()

    };


    msg.payload = devices;

    return msg;


} catch (err) {

    global.set("devices", null);


    node.status({
        fill: "red",
        shape: "ring",
        text: "ERROR"
    });


    msg.startupEvent = {

        component: component,

        ok: false,

        count: 0,

        error: err.message,

        timestamp: new Date().toISOString()

    };


    msg.payload = null;

    return msg;
}

// ======================================================
// STORE DRIVERS
// ======================================================

const component = "drivers";

const fs = global.get("fs");
const path = global.get("path");


// ------------------------------------------------------
// FUNCIÓN DE ERROR
// ------------------------------------------------------

function fail(message) {

    global.set("drivers", null);

    node.status({
        fill: "red",
        shape: "ring",
        text: "ERROR"
    });

    msg.startupEvent = {

        component: component,

        ok: false,

        count: 0,

        error: message,

        timestamp: new Date().toISOString()

    };

    msg.payload = null;

    return msg;
}


// ------------------------------------------------------
// VALIDAR LIBRERÍAS
// ------------------------------------------------------

if (!fs || !path) {

    return fail(
        "fs o path no están cargados."
    );
}


// ------------------------------------------------------
// CARGAR DRIVERS
// ------------------------------------------------------

try {

    const drivers = {};

    const files = fs
        .readdirSync("/drivers")
        .filter(file => file.endsWith(".json"));


    if (files.length === 0) {

        return fail(
            "No se encontraron drivers JSON en /drivers."
        );
    }


    for (const file of files) {

        const fullPath =
            path.join("/drivers", file);

        let driver;


        try {

            const json =
                fs.readFileSync(fullPath, "utf8");

            driver = JSON.parse(json);

        } catch (err) {

            throw new Error(
                `${file}: ${err.message}`
            );
        }


        if (
            !driver ||
            typeof driver !== "object" ||
            Array.isArray(driver)
        ) {

            throw new Error(
                `${file}: el contenido no es un objeto JSON válido.`
            );
        }


        const driverId =
            path.basename(file, ".json");


        drivers[driverId] = driver;
    }


    // --------------------------------------------------
    // GUARDAR
    // --------------------------------------------------

    global.set("drivers", drivers);


    const driverIds =
        Object.keys(drivers);


    node.status({
        fill: "green",
        shape: "dot",
        text: driverIds.length + " drivers"
    });


    // --------------------------------------------------
    // EVENTO STARTUP
    // --------------------------------------------------

    msg.startupEvent = {

        component: component,

        ok: true,

        count: driverIds.length,

        error: null,

        timestamp: new Date().toISOString()

    };


    msg.payload = drivers;

    return msg;


} catch (err) {

    return fail(err.message);
}

// ======================================================
// SYSTEM STATE
// ======================================================
//
// Representa el estado GLOBAL del BMS.
//
// PRIORIDAD:
//
// 1. FAULT
// 2. READY
// 3. LOADING
//
// IMPORTANTE:
// Los mensajes mantienen msg.startup durante todo el
// recorrido del Startup.
//
// Por eso READY y FAULT deben evaluarse ANTES que
// LOADING.
// ======================================================


// ======================================================
// 1. FAULT
// ======================================================

if (
    msg.payload &&
    msg.payload.status === "FAULT"
) {

    global.set(
        "systemReady",
        false
    );


    node.status({

        fill: "red",

        shape: "dot",

        text: "FAULT"

    });


    return null;
}


// ======================================================
// 2. READY
// ======================================================

if (
    msg.validation &&
    msg.validation.ok === true
) {

    let state =
        global.get("startupState");


    if (!state) {

        global.set(
            "systemReady",
            false
        );


        node.status({

            fill: "red",

            shape: "ring",

            text: "NO STARTUP STATE"

        });


        node.error(
            "No existe startupState."
        );


        return null;
    }


    // --------------------------------------------------
    // ACTUALIZAR ESTADO
    // --------------------------------------------------

    const now =
        Date.now();


    state.status =
        "READY";


    state.readyAt =
        new Date(now).toISOString();


    const startedAt =
        Date.parse(state.startedAt);


    state.durationMs =
        Number.isFinite(startedAt)
            ? now - startedAt
            : null;


    global.set(
        "startupState",
        state
    );


    // --------------------------------------------------
    // HABILITAR SISTEMA
    // --------------------------------------------------

    global.set(
        "systemReady",
        true
    );


    // --------------------------------------------------
    // ESTADO VISUAL
    // --------------------------------------------------

    node.status({

        fill: "green",

        shape: "dot",

        text: "READY"

    });


    node.warn(
        "========== BMS READY =========="
    );


    // --------------------------------------------------
    // MENSAJE DE SALIDA
    // --------------------------------------------------

    msg.payload = {

        status: "READY",

        timestamp:
            state.readyAt,

        startupDurationMs:
            state.durationMs,

        components: {

            gateways:
                state.components.gateways.count,

            devices:
                state.components.devices.count,

            drivers:
                state.components.drivers.count

        },

        warnings:
            state.validation?.warnings || []

    };


    return msg;
}


// ======================================================
// 3. LOADING
// ======================================================

if (
    msg.startup &&
    msg.startup.action === "LOAD_ALL"
) {

    global.set(
        "systemReady",
        false
    );


    node.status({

        fill: "yellow",

        shape: "ring",

        text: "LOADING"

    });


    return null;
}


// ======================================================
// 4. MENSAJE NO RECONOCIDO
// ======================================================

node.warn(
    "System State recibió un mensaje sin estado reconocido."
);

return null;

// ======================================================
// INIT STARTUP STATE
// ======================================================
// Inicializa un nuevo ciclo de arranque/configuración.
//
// OUTPUT 1:
//   Dispara la carga de gateways, devices y drivers.
//
// OUTPUT 2:
//   Dispara el watchdog de timeout del Startup.
// ======================================================

const now = Date.now();

const runId =
    now.toString(36) +
    "-" +
    Math.random().toString(16).slice(2);


// ------------------------------------------------------
// ESTADO INICIAL
// ------------------------------------------------------

const startupState = {

    runId: runId,

    status: "LOADING",

    startedAt: new Date(now).toISOString(),

    readyAt: null,

    durationMs: null,

    components: {

        gateways: {
            reported: false,
            ok: false,
            count: 0,
            error: null
        },

        devices: {
            reported: false,
            ok: false,
            count: 0,
            error: null
        },

        drivers: {
            reported: false,
            ok: false,
            count: 0,
            error: null
        }

    },

    validation: {
        ok: false,
        errors: [],
        warnings: []
    },

    errors: []

};


// ------------------------------------------------------
// CERRAR EL GATE DEL SISTEMA
// ------------------------------------------------------

global.set("systemReady", false);

global.set("startupState", startupState);


// ------------------------------------------------------
// ESTADO VISUAL
// ------------------------------------------------------

node.status({
    fill: "yellow",
    shape: "ring",
    text: "LOADING"
});


// ------------------------------------------------------
// MENSAJE DE STARTUP
// ------------------------------------------------------

msg.startupRunId = runId;

msg.startup = {
    action: "LOAD_ALL",
    runId: runId,
    timestamp: startupState.startedAt
};


// Creamos dos mensajes independientes.
const loadMsg = RED.util.cloneMessage(msg);
const timeoutMsg = RED.util.cloneMessage(msg);


// OUTPUT 1 = carga
// OUTPUT 2 = watchdog

return [
    loadMsg,
    timeoutMsg
];

// ======================================================
// STARTUP COORDINATOR
// ======================================================
//
// Espera el reporte de:
//
// gateways
// devices
// drivers
//
// Ningún componente individual puede declarar
// al BMS como READY.
// ======================================================

const event = msg.startupEvent;

let state = global.get("startupState");


// ------------------------------------------------------
// VALIDACIONES
// ------------------------------------------------------

if (!state) {

    node.warn(
        "Startup Coordinator recibió un mensaje sin startupState."
    );

    return [null, null];
}


if (!event || !event.component) {

    node.warn(
        "Startup Coordinator recibió un mensaje sin startupEvent."
    );

    return [null, null];
}


// Ignorar mensajes pertenecientes a un startup anterior.

if (
    msg.startupRunId &&
    msg.startupRunId !== state.runId
) {

    node.warn(
        "Ignorado mensaje perteneciente a un Startup anterior."
    );

    return [null, null];
}


if (!state.components[event.component]) {

    node.warn(
        `Componente de Startup desconocido: ${event.component}`
    );

    return [null, null];
}


// ------------------------------------------------------
// REGISTRAR RESULTADO
// ------------------------------------------------------

state.components[event.component] = {

    reported: true,

    ok: event.ok === true,

    count: Number(event.count || 0),

    error: event.error || null

};


global.set("startupState", state);


// ------------------------------------------------------
// VER CUÁNTOS RESPONDIERON
// ------------------------------------------------------

const componentNames =
    Object.keys(state.components);


const reportedCount =
    componentNames.filter(
        name =>
            state.components[name].reported === true
    ).length;


node.status({

    fill: "yellow",

    shape: "ring",

    text:
        `LOADING ${reportedCount}/${componentNames.length}`

});


// ------------------------------------------------------
// TODAVÍA FALTA ALGÚN COMPONENTE
// ------------------------------------------------------

if (reportedCount < componentNames.length) {

    return [null, null];
}


// ------------------------------------------------------
// EVITAR EJECUTAR DOS VECES
// ------------------------------------------------------

if (state.coordinatorCompleted === true) {

    return [null, null];
}


state.coordinatorCompleted = true;


// ------------------------------------------------------
// COMPROBAR ERRORES
// ------------------------------------------------------

const failedComponents =
    componentNames.filter(
        name =>
            state.components[name].ok !== true
    );


if (failedComponents.length > 0) {

    const errors =
        failedComponents.map(name => {

            const component =
                state.components[name];

            return (
                `${name}: ` +
                (component.error || "error desconocido")
            );
        });


    state.status = "FAULT";

    state.errors = errors;

    global.set("startupState", state);

    global.set("systemReady", false);


    node.status({

        fill: "red",

        shape: "ring",

        text: "FAULT"

    });


    msg.payload = {

        status: "FAULT",

        stage: "LOAD",

        errors: errors

    };


    return [null, msg];
}


// ------------------------------------------------------
// TODOS CARGADOS CORRECTAMENTE
// ------------------------------------------------------

state.status = "VALIDATING";

global.set("startupState", state);


node.status({

    fill: "yellow",

    shape: "dot",

    text: "VALIDATING"

});


msg.payload = {

    gateways:
        state.components.gateways.count,

    devices:
        state.components.devices.count,

    drivers:
        state.components.drivers.count

};


return [msg, null];

// ======================================================
// STARTUP TIMEOUT CHECK
// ======================================================

const state =
    global.get("startupState");


// No existe Startup activo.

if (!state) {
    return null;
}


// Este timeout pertenece a un Startup viejo.

if (
    msg.startupRunId !== state.runId
) {
    return null;
}


// El Startup ya terminó.

if (
    state.status === "READY" ||
    state.status === "FAULT"
) {
    return null;
}


// ------------------------------------------------------
// COMPONENTES QUE NO RESPONDIERON
// ------------------------------------------------------

const missing =
    Object.keys(state.components)
        .filter(
            name =>
                state.components[name].reported !== true
        );


if (missing.length === 0) {

    // Todos reportaron.
    // Si estamos acá, la validación está procesándose.
    return null;
}


// ------------------------------------------------------
// TIMEOUT
// ------------------------------------------------------

msg.payload = {

    status: "FAULT",

    stage: "TIMEOUT",

    errors: missing.map(
        name =>
            `Timeout esperando componente: ${name}`
    )

};


return msg;

// ======================================================
// VALIDATE CONFIGURATION
// ======================================================

const gateways = global.get("gateways");
const devices = global.get("devices");
const drivers = global.get("drivers");

const errors = [];
const warnings = [];


// ------------------------------------------------------
// HELPERS
// ------------------------------------------------------

function isObject(value) {

    return (
        value !== null &&
        typeof value === "object" &&
        !Array.isArray(value)
    );
}


const supportedTypes = new Set([

    "bool",
    "uint16",
    "int16",
    "uint32",
    "int32",
    "float",
    "bitmask"

]);


const readFunctionCodes =
    new Set([1, 2, 3, 4]);


// ======================================================
// CONFIGURACIONES PRINCIPALES
// ======================================================

if (!isObject(gateways)) {

    errors.push(
        "global.gateways no es válido."
    );
}


if (!isObject(devices)) {

    errors.push(
        "global.devices no es válido."
    );
}


if (!isObject(drivers)) {

    errors.push(
        "global.drivers no es válido."
    );
}


// Si las estructuras base no existen,
// no tiene sentido seguir validando.

if (errors.length === 0) {

    // ==================================================
    // DEVICES
    // ==================================================

    for (
        const [deviceId, device]
        of Object.entries(devices)
    ) {

        if (!isObject(device)) {

            errors.push(
                `Device ${deviceId}: configuración inválida.`
            );

            continue;
        }


        // ----------------------------------------------
        // GATEWAY
        // ----------------------------------------------

        if (
            typeof device.gateway !== "string" ||
            device.gateway.trim() === ""
        ) {

            errors.push(
                `Device ${deviceId}: gateway inválido.`
            );

        } else if (
            !Object.prototype.hasOwnProperty.call(
                gateways,
                device.gateway
            )
        ) {

            errors.push(
                `Device ${deviceId}: gateway ` +
                `${device.gateway} inexistente.`
            );
        }


        // ----------------------------------------------
        // DRIVER
        // ----------------------------------------------

        if (
            typeof device.driver !== "string" ||
            device.driver.trim() === ""
        ) {

            errors.push(
                `Device ${deviceId}: driver inválido.`
            );

        } else if (
            !Object.prototype.hasOwnProperty.call(
                drivers,
                device.driver
            )
        ) {

            errors.push(
                `Device ${deviceId}: driver ` +
                `${device.driver} inexistente.`
            );
        }


        // ----------------------------------------------
        // MODBUS SLAVE
        // ----------------------------------------------

        const slave =
            Number(device.slave);


        if (
            !Number.isInteger(slave) ||
            slave < 1 ||
            slave > 247
        ) {

            errors.push(
                `Device ${deviceId}: slave Modbus inválido ` +
                `(${device.slave}).`
            );
        }
    }


    // ==================================================
    // DRIVERS
    // ==================================================

    for (
        const [driverId, driver]
        of Object.entries(drivers)
    ) {

        if (!isObject(driver)) {

            errors.push(
                `Driver ${driverId}: configuración inválida.`
            );

            continue;
        }


        if (!isObject(driver.variables)) {

            errors.push(
                `Driver ${driverId}: no contiene variables válidas.`
            );

            continue;
        }


        const variableNames =
            Object.keys(driver.variables);


        if (variableNames.length === 0) {

            warnings.push(
                `Driver ${driverId}: no contiene variables.`
            );
        }


        // ----------------------------------------------
        // VARIABLES
        // ----------------------------------------------

        for (
            const [variableId, variable]
            of Object.entries(driver.variables)
        ) {

            if (!isObject(variable)) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `variable inválida.`
                );

                continue;
            }


            // Solo validamos parámetros de lectura
            // cuando read === true.

            if (variable.read !== true) {
                continue;
            }


            // ------------------------------------------
            // FUNCTION CODE
            // ------------------------------------------

            const fc =
                Number(variable.fc);


            if (
                !Number.isInteger(fc) ||
                !readFunctionCodes.has(fc)
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `FC de lectura inválido (${variable.fc}).`
                );
            }


            // ------------------------------------------
            // ADDRESS
            // ------------------------------------------

            const address =
                Number(variable.address);


            if (
                !Number.isInteger(address) ||
                address < 0
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `address inválido (${variable.address}).`
                );
            }


            // ------------------------------------------
            // QUANTITY
            // ------------------------------------------

            const quantity =
                Number(variable.quantity);


            if (
                !Number.isInteger(quantity) ||
                quantity < 1
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `quantity inválido (${variable.quantity}).`
                );
            }


            // ------------------------------------------
            // TYPE
            // ------------------------------------------

            if (
                typeof variable.type !== "string" ||
                !supportedTypes.has(variable.type)
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `tipo no soportado (${variable.type}).`
                );
            }


            // ------------------------------------------
            // SCAN
            // ------------------------------------------

            if (variable.scan !== undefined) {

                const scan =
                    Number(variable.scan);


                if (
                    !Number.isFinite(scan) ||
                    scan < 0
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `scan inválido (${variable.scan}).`
                    );
                }
            }


            // ------------------------------------------
            // MULTIPLIER
            // ------------------------------------------

            if (
                variable.multiplier !== undefined &&
                !Number.isFinite(
                    Number(variable.multiplier)
                )
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `multiplier inválido.`
                );
            }


            // ------------------------------------------
            // DECIMALS
            // ------------------------------------------

            if (variable.decimals !== undefined) {

                const decimals =
                    Number(variable.decimals);


                if (
                    !Number.isInteger(decimals) ||
                    decimals < 0
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `decimals inválido.`
                    );
                }
            }


            // ------------------------------------------
            // BITMASK
            // ------------------------------------------

            if (variable.type === "bitmask") {

                if (!isObject(variable.bits)) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `bitmask sin bits configurados.`
                    );

                } else {

                    for (
                        const [bitIndex, bitConfig]
                        of Object.entries(variable.bits)
                    ) {

                        const index =
                            Number(bitIndex);


                        if (
                            !Number.isInteger(index) ||
                            index < 0 ||
                            index > 15
                        ) {

                            errors.push(
                                `Driver ${driverId} / ${variableId}: ` +
                                `bit ${bitIndex} inválido.`
                            );
                        }


                        if (!isObject(bitConfig)) {

                            errors.push(
                                `Driver ${driverId} / ${variableId}: ` +
                                `configuración del bit ${bitIndex} inválida.`
                            );

                            continue;
                        }


                        if (
                            typeof bitConfig.point !== "string" ||
                            bitConfig.point.trim() === ""
                        ) {

                            errors.push(
                                `Driver ${driverId} / ${variableId}: ` +
                                `bit ${bitIndex} sin point.`
                            );
                        }


                        if (
                            typeof bitConfig.name !== "string" ||
                            bitConfig.name.trim() === ""
                        ) {

                            errors.push(
                                `Driver ${driverId} / ${variableId}: ` +
                                `bit ${bitIndex} sin name.`
                            );
                        }
                    }
                }
            }
        }
    }
}


// ======================================================
// ACTUALIZAR STARTUP STATE
// ======================================================

let state =
    global.get("startupState") || {};


state.validation = {

    ok: errors.length === 0,

    errors: errors,

    warnings: warnings

};


global.set(
    "startupState",
    state
);


// ======================================================
// RESULTADO
// ======================================================

if (errors.length > 0) {

    node.status({

        fill: "red",

        shape: "ring",

        text: errors.length + " errores"

    });


    msg.payload = {

        status: "FAULT",

        stage: "VALIDATION",

        errors: errors,

        warnings: warnings

    };


    return [
        null,
        msg
    ];
}


// ------------------------------------------------------
// VALIDACIÓN CORRECTA
// ------------------------------------------------------

node.status({

    fill: "green",

    shape: "dot",

    text: "CONFIG OK"

});


msg.validation = {

    ok: true,

    warnings: warnings

};


return [
    msg,
    null
];

// ======================================================
// STARTUP FAULT
// ======================================================
//
// Este nodo procesa los errores del Startup.
//
// También recibe el estado READY desde System State
// únicamente para limpiar su indicador visual anterior.
//
// IMPORTANTE:
// Solo un mensaje con payload.status === "FAULT"
// puede generar una falla.
// ======================================================


// ======================================================
// 1. SISTEMA RECUPERADO / READY
// ======================================================
//
// System State envía:
//
// msg.payload.status = "READY"
//
// En este caso NO procesamos ninguna falla.
// Solamente limpiamos el indicador visual del nodo.
// ======================================================

if (
    msg.payload &&
    msg.payload.status === "READY"
) {

    node.status({});

